section.artwork:
Client                                               Server

ClientHello
  + key_share
  + signature_algorithms
  + PinningTicket         -------->
                                                ServerHello
                                                + key_share
                                      {EncryptedExtensions
                                           + PinningTicket}
                                      {CertificateRequest*}
                                             {Certificate*}
                                       {CertificateVerify*}
                          <--------              {Finished}
{Certificate*}
{CertificateVerify*}
{Finished}                -------->
[Application Data]        <------->      [Application Data]

       *  Indicates optional or situation-dependent
          messages that are not always sent.

       {} Indicates messages protected using keys
          derived from the ephemeral secret.

       [] Indicates messages protected using keys
          derived from the master secret.

section.sourcecode:
 opaque pinning_ticket<0..2^16-1>;

 opaque pinning_proof<0..2^8-1>;

 struct {
   select (Role) {
     case client:
       pinning_ticket ticket<0..2^16-1>; //最初の接続では省略

     case server:
       pinning_proof proof<0..2^8-1>; //最初の接続では証明なし
       pinning_ticket ticket<0..2^16-1>; //段階的縮小時は省略
       uint32 lifetime;
   }
} PinningTicketExtension;
